 "content": "from collections import Counter, defaultdict

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=[]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); q.append((yy,xx))
        r0=min(y for y,x in cells); c0=min(x for y,x in cells)
        shape=tuple(sorted((y-r0,x-c0) for y,x in cells))
        comps.append({'color':color,'cells':cells,'shape':shape,'r0':r0,'c0':c0,
                      'r1':max(y for y,x in cells),'c1':max(x for y,x in cells)})
    # Find the long, thin L-shaped color guide.
    def guide_score(o):
      cells=o['cells']; rc=Counter(r for r,c in cells); cc=Counter(c for r,c in cells)
      return max(rc.values())+max(cc.values()) - 0.10*len(cells)
    guide=max(comps,key=guide_score)
    gc=guide['color']; rc=Counter(r for r,c in guide['cells']); cc=Counter(c for r,c in guide['cells'])
    hr=max(rc,key=rc.get); vc=max(cc,key=cc.get)
    rowcells=[c for r,c in guide['cells'] if r==hr]
    # direction of the guide's horizontal arm away from the elbow
    right=max(rowcells)>vc
    groups=defaultdict(list)
    for o in comps:
      if o is not guide: groups[o['shape']].append(o)
    pairs=[]
    for shape,items in groups.items():
      if len(items)<2: continue
      # Repeated object pair; use the two instances on opposite sides of stem.
      for i in range(len(items)):
       for j in range(i+1,len(items)):
        a,b=items[i],items[j]
        if (a['c1']<vc and b['c0']>vc) or (b['c1']<vc and a['c0']>vc):
          left=a if a['c1']<vc else b
          rightobj=b if left is a else a
          target=left if right else rightobj
          pairs.append((len(shape),target))
    if pairs:
      target=max(pairs,key=lambda p:p[0])[1]
    else:
      # fallback: nearest object on the side opposite the horizontal arm
      candidates=[]
      for o in comps:
        if o is guide: continue
        if (right and o['c1']<vc) or ((not right) and o['c0']>vc):
          candidates.append((abs(o['r0']-hr)+abs(o['c0']-vc),o))
      if not candidates: return [row[:] for row in grid]
      target=min(candidates,key=lambda p:p[0])[1]
    out=[row[:] for row in grid]
    for r,c in target['cells']: out[r][c]=gc
    return out
